bool c[21][21];

int dp[21][2097152];
int nop(int i,int n,int w)
{
   if(i==n)
   {
   	if(w==0)
   		return 1;
   	return 0;
   } 
   if(dp[i][w]!=-1){
   
   	return dp[i][w];}
   int ans=0;
   for(int j=0;j<n;j++)
   {
   	if(((1<<j)&(w))&&c[i][j])
   	{
   		ans=(ans+nop(i+1,n,((w)^(1<<j))))%mod;
   	}
   }
   return dp[i][w]=ans;
}
void solve()
{
	int n;
	cin>>n;
	memset(dp,-1,sizeof(dp));
	for (int i = 0; i < n; ++i)
	{
		for(int j=0;j<n;j++)
			cin>>c[i][j];
	}
	cout<<nop(0,n,(1<<(n))-1)<<endl;


}
main()
{
	i_n();
	solve();
	

}
